var o=[{title:`Quão complexo é um exercício`,text:`Uma remada em máquina com apoio move-se num trajeto estável. Um levantamento romeno com uma perna pede equilíbrio, controlo do tronco e coordenação da anca, e um swing de kettlebell acrescenta velocidade e sincronização. Pode ser muito forte e, ainda assim, ser novato numa destas competências.`},{title:`Vá do previsível ao desafiante`,text:`Comece com posições estáveis e repetições mais lentas e aprenda uma competência nova de cada vez. Depois torne o exercício mais difícil retirando apoio, alterando a alavanca, aumentando a amplitude ou acrescentando velocidade controlada. Uma progressão deve manter o objetivo do movimento e evitar alterar todas as exigências ao mesmo tempo.`},{title:`A fadiga altera a coordenação`,text:`Um exercício que fez bem no início de uma sessão pode ficar instável depois de muitas repetições. Faça os exercícios de grande competência mais cedo, descanse mais quando precisar e termine uma série quando o equilíbrio ou o controlo falharem. Os exercícios balísticos complexos costumam ser uma má primeira escolha para um iniciante cansado.`},{title:`Exemplo`,text:`Se estiver a aprender afundos, pode começar com split squats agarrado a um corrimão, passar a afundos para trás sem apoio e experimentar afundos com deslocamento mais tarde. Uma variação mais rápida não é automaticamente melhor.`},{title:`Usar o TrainUp`,text:`Quando o TrainUp constrói o seu plano, escolhe exercícios que se adaptam ao seu nível e coordenação, bem como às suas limitações e ao seu equipamento.`}];var i=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Orientações práticas do ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var s={sections:o,sources:i};export{s as default,o as sections,i as sources};